"""Shared helpers for parsing and verification."""

from __future__ import annotations

from contextlib import contextmanager
from dataclasses import dataclass
import re
import signal
import threading
from typing import Iterable, Iterator

import sympy as sp
from sympy import Basic, MatrixBase

from .errors import ParseTimeoutError, VerifyTimeoutError

ParsedMath = Basic | MatrixBase | str

_REL_REPLACEMENTS = {
    "≤": "<=",
    "≥": ">=",
    "≠": "!=",
    "−": "-",
    "–": "-",
    "—": "-",
    "×": "*",
    "÷": "/",
    "∪": " union ",
    "∩": " intersection ",
}

_PUNCTUATION_TRIM = " \t\r\n.,;:!?\"'`"


def normalize_unicode_math(text: str) -> str:
    for source, target in _REL_REPLACEMENTS.items():
        text = text.replace(source, target)
    return text.replace("\u00a0", " ")


def strip_noise(text: str) -> str:
    text = normalize_unicode_math(text.strip())
    text = re.sub(r"\*{1,2}\s*final answer\s*\*{1,2}", "final answer", text, flags=re.I)
    text = re.sub(r"\*{1,2}", "", text)
    return text.strip(_PUNCTUATION_TRIM)


def strip_outer_math_delimiters(text: str) -> str:
    text = text.strip()
    pairs = [
        ("$$", "$$"),
        ("\\[", "\\]"),
        ("\\(", "\\)"),
        ("$", "$"),
    ]
    changed = True
    while changed:
        changed = False
        for left, right in pairs:
            if text.startswith(left) and text.endswith(right) and len(text) >= len(left) + len(right):
                text = text[len(left) : len(text) - len(right)].strip()
                changed = True
    return text


def unique_preserve_order(items: Iterable[ParsedMath]) -> list[ParsedMath]:
    unique: list[ParsedMath] = []
    seen: set[str] = set()
    for item in items:
        key = repr(item)
        if key not in seen:
            seen.add(key)
            unique.append(item)
    return unique


def split_top_level(text: str, delimiter: str = ",") -> list[str]:
    items: list[str] = []
    depth_round = 0
    depth_square = 0
    depth_curly = 0
    escaped = False
    current: list[str] = []
    for char in text:
        if escaped:
            current.append(char)
            escaped = False
            continue
        if char == "\\":
            current.append(char)
            escaped = True
            continue
        if char == "(":
            depth_round += 1
        elif char == ")":
            depth_round = max(0, depth_round - 1)
        elif char == "[":
            depth_square += 1
        elif char == "]":
            depth_square = max(0, depth_square - 1)
        elif char == "{":
            depth_curly += 1
        elif char == "}":
            depth_curly = max(0, depth_curly - 1)
        if (
            char == delimiter
            and depth_round == 0
            and depth_square == 0
            and depth_curly == 0
        ):
            items.append("".join(current).strip())
            current = []
            continue
        current.append(char)
    if current:
        items.append("".join(current).strip())
    return [item for item in items if item]


def find_matching_brace(text: str, start_index: int) -> int:
    depth = 0
    escaped = False
    for index in range(start_index, len(text)):
        char = text[index]
        if escaped:
            escaped = False
            continue
        if char == "\\":
            escaped = True
            continue
        if char == "{":
            depth += 1
        elif char == "}":
            depth -= 1
            if depth == 0:
                return index
    return -1


def extract_command_braces(text: str, command: str) -> list[tuple[int, int, str]]:
    matches: list[tuple[int, int, str]] = []
    start = 0
    needle = "\\" + command
    while True:
        index = text.find(needle, start)
        if index < 0:
            return matches
        brace_start = text.find("{", index + len(needle))
        if brace_start < 0:
            start = index + len(needle)
            continue
        brace_end = find_matching_brace(text, brace_start)
        if brace_end < 0:
            start = brace_start + 1
            continue
        matches.append((index, brace_end + 1, text[brace_start + 1 : brace_end]))
        start = brace_end + 1


@dataclass(frozen=True)
class Candidate:
    text: str
    kind: str
    priority: int
    position: int


def coerce_to_sympy(value: object) -> ParsedMath | None:
    if isinstance(value, (Basic, MatrixBase, str)):
        return value
    if isinstance(value, set):
        return sp.FiniteSet(*(coerce_to_sympy(item) for item in value))
    if isinstance(value, tuple):
        return sp.Tuple(*(coerce_to_sympy(item) for item in value))
    return None


def normalize_interval(interval: sp.Interval) -> sp.Interval:
    if interval.start <= interval.end:
        return interval
    return sp.Interval(
        interval.end,
        interval.start,
        left_open=interval.right_open,
        right_open=interval.left_open,
    )


def normalize_parsed_object(value: object) -> ParsedMath:
    coerced = coerce_to_sympy(value)
    if coerced is None:
        raise TypeError(f"Unsupported parsed object: {type(value)!r}")
    if isinstance(coerced, sp.Interval):
        return normalize_interval(coerced)
    if isinstance(coerced, sp.Set) and isinstance(coerced, sp.FiniteSet):
        return sp.FiniteSet(*(normalize_parsed_object(arg) for arg in coerced))
    if isinstance(coerced, sp.Tuple):
        return sp.Tuple(*(normalize_parsed_object(arg) for arg in coerced))
    return coerced


def is_main_thread() -> bool:
    return threading.current_thread() is threading.main_thread()


@contextmanager
def time_limit(seconds: int | None, timeout_exc: type[Exception]) -> Iterator[None]:
    if not seconds or seconds <= 0 or not is_main_thread():
        yield
        return

    def _raise_timeout(signum: int, frame: object) -> None:
        raise timeout_exc()

    previous_handler = signal.getsignal(signal.SIGALRM)
    signal.signal(signal.SIGALRM, _raise_timeout)
    signal.setitimer(signal.ITIMER_REAL, float(seconds))
    try:
        yield
    finally:
        signal.setitimer(signal.ITIMER_REAL, 0.0)
        signal.signal(signal.SIGALRM, previous_handler)


def parsing_time_limit(seconds: int | None) -> Iterator[None]:
    return time_limit(seconds, ParseTimeoutError)


def verify_time_limit(seconds: int | None) -> Iterator[None]:
    return time_limit(seconds, VerifyTimeoutError)

