class MathVerifyError(Exception):
    """Base exception for the package."""


class ParseTimeoutError(MathVerifyError):
    """Raised when parsing exceeds the configured timeout."""


class VerifyTimeoutError(MathVerifyError):
    """Raised when verification exceeds the configured timeout."""

